Out_Q_Node* out_q_free_create( void  ) 
{
    Out_Q_Node *node = (Out_Q_Node*)os_mem_request( sizeof( struct s_Out_Q_Node ) ) ;

	if( node )
    {
        node->out = out_create( NULL );
    }
        
	return node ; 
}

